func translate(word string) string {
    // Rule 1: starts with vowel, xr, or yt
    if len(word) > 0 && isVowel(word[0]) {
        return word + "ay"
    }
    if hasPrefix(word, "xr") || hasPrefix(word, "yt") {
        return word + "ay"
    }

    // Find where the consonant cluster ends
    // The cluster is the leading consonants. It ends at the first vowel,
    // OR at "qu" (include qu), OR at "y" (treat y as vowel).

    i := 0
    for i < len(word) {
        c := word[i]
        if isVowel(c) {
            break
        }
        // c is a consonant (including q, y, etc.)
        if c == 'q' && i+1 < len(word) && word[i+1] == 'u' {
            // include the qu
            i += 2
            break
        }
        if c == 'y' {
            // y treated as vowel here (it's after at least one consonant since we didn't handle start)
            break
        }
        i++
    }

    return word[i:] + word[:i] + "ay"
}
