package piglatin

import "strings"

// Sentence translates an English sentence into Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = translate(w)
	}
	return strings.Join(words, " ")
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

// translate applies the Pig Latin rules to a single word.
func translate(word string) string {
	if len(word) == 0 {
		return word
	}

	// Rule 1: begins with a vowel, or with "xr" or "yt".
	if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return word + "ay"
	}

	// Find the end of the leading consonant cluster.
	// - Stop at the first vowel.
	// - Include a "qu" in the moved part (Rule 3).
	// - Treat "y" as a vowel once it follows at least one consonant (Rule 4),
	//   but keep it a consonant at the very start of the word.
	i := 0
	for i < len(word) {
		c := word[i]
		if isVowel(c) {
			break
		}
		if c == 'q' && i+1 < len(word) && word[i+1] == 'u' {
			i += 2
			break
		}
		if c == 'y' && i > 0 {
			break
		}
		i++
	}

	return word[i:] + word[:i] + "ay"
}
